			annotationNode.addError(BUILDER_NODE_NOT_SUPPORTED_ERR);
			return;
		}

		if (fillParametersFrom != null) {
			for (JavacNode param : fillParametersFrom.down()) {
				if (param.getKind() != Kind.ARGUMENT) continue;
